    55  PLY::EDataType PLY::Property::ParseDataType(std::vector<char> &buffer) {
    56      ai_assert(!buffer.empty());
    57
    58      PLY::EDataType eOut = PLY::EDT_INVALID;
    59
    60      if (PLY::DOM::TokenMatch(buffer, "char", 4) ||
    61              PLY::DOM::TokenMatch(buffer, "int8", 4)) {
    62          eOut = PLY::EDT_Char;
    63      } else if (PLY::DOM::TokenMatch(buffer, "uchar", 5) ||
    64                 PLY::DOM::TokenMatch(buffer, "uint8", 5)) {
    65          eOut = PLY::EDT_UChar;
    66      } else if (PLY::DOM::TokenMatch(buffer, "short", 5) ||
    67                 PLY::DOM::TokenMatch(buffer, "int16", 5)) {
    68          eOut = PLY::EDT_Short;
    69      } else if (PLY::DOM::TokenMatch(buffer, "ushort", 6) ||
    70                 PLY::DOM::TokenMatch(buffer, "uint16", 6)) {
    71          eOut = PLY::EDT_UShort;
    72      } else if (PLY::DOM::TokenMatch(buffer, "int32", 5) || PLY::DOM::TokenMatch(buffer, "int", 3)) {
    73          eOut = PLY::EDT_Int;
    74      } else if (PLY::DOM::TokenMatch(buffer, "uint32", 6) || PLY::DOM::TokenMatch(buffer, "uint", 4)) {
    75          eOut = PLY::EDT_UInt;
    76      } else if (PLY::DOM::TokenMatch(buffer, "float", 5) || PLY::DOM::TokenMatch(buffer, "float32", 7)) {
    77          eOut = PLY::EDT_Float;
    78      } else if (PLY::DOM::TokenMatch(buffer, "double64", 8) || PLY::DOM::TokenMatch(buffer, "double", 6) ||
    79                 PLY::DOM::TokenMatch(buffer, "float64", 7)) {
    80          eOut = PLY::EDT_Double;
    81      }
    82      if (PLY::EDT_INVALID == eOut) {
    83          ASSIMP_LOG_INFO("Found unknown data type in PLY file. This is OK");
    84      }
    85
    86      return eOut;
    87  }
