    90  PLY::ESemantic PLY::Property::ParseSemantic(std::vector<char> &buffer) {
    91      ai_assert(!buffer.empty());
    92
    93      PLY::ESemantic eOut = PLY::EST_INVALID;
    94      if (PLY::DOM::TokenMatch(buffer, "red", 3)) {
    95          eOut = PLY::EST_Red;
