    97          eOut = PLY::EST_Green;
    98      } else if (PLY::DOM::TokenMatch(buffer, "blue", 4)) {
    99          eOut = PLY::EST_Blue;
   100      } else if (PLY::DOM::TokenMatch(buffer, "alpha", 5)) {
   101          eOut = PLY::EST_Alpha;
   102      } else if (PLY::DOM::TokenMatch(buffer, "vertex_index", 12) || PLY::DOM::TokenMatch(buffer, "vertex_indices", 14)) {
   103          eOut = PLY::EST_VertexIndex;
   104      } else if (PLY::DOM::TokenMatch(buffer, "texcoord", 8)) // Manage uv coords on faces
   105      {
   106          eOut = PLY::EST_TextureCoordinates;
   107      } else if (PLY::DOM::TokenMatch(buffer, "material_index", 14)) {
   108          eOut = PLY::EST_MaterialIndex;
   109      } else if (PLY::DOM::TokenMatch(buffer, "ambient_red", 11)) {
   110          eOut = PLY::EST_AmbientRed;
   111      } else if (PLY::DOM::TokenMatch(buffer, "ambient_green", 13)) {
   112          eOut = PLY::EST_AmbientGreen;
   113      } else if (PLY::DOM::TokenMatch(buffer, "ambient_blue", 12)) {
   114          eOut = PLY::EST_AmbientBlue;
   115      } else if (PLY::DOM::TokenMatch(buffer, "ambient_alpha", 13)) {
   116          eOut = PLY::EST_AmbientAlpha;
   117      } else if (PLY::DOM::TokenMatch(buffer, "diffuse_red", 11)) {
   118          eOut = PLY::EST_DiffuseRed;
   119      } else if (PLY::DOM::TokenMatch(buffer, "diffuse_green", 13)) {
   120          eOut = PLY::EST_DiffuseGreen;
   121      } else if (PLY::DOM::TokenMatch(buffer, "diffuse_blue", 12)) {
   122          eOut = PLY::EST_DiffuseBlue;
   123      } else if (PLY::DOM::TokenMatch(buffer, "diffuse_alpha", 13)) {
   124          eOut = PLY::EST_DiffuseAlpha;
   125      } else if (PLY::DOM::TokenMatch(buffer, "specular_red", 12)) {
   126          eOut = PLY::EST_SpecularRed;
   127      } else if (PLY::DOM::TokenMatch(buffer, "specular_green", 14)) {
   128          eOut = PLY::EST_SpecularGreen;
   129      } else if (PLY::DOM::TokenMatch(buffer, "specular_blue", 13)) {
   130          eOut = PLY::EST_SpecularBlue;
   131      } else if (PLY::DOM::TokenMatch(buffer, "specular_alpha", 14)) {
   132          eOut = PLY::EST_SpecularAlpha;
   133      } else if (PLY::DOM::TokenMatch(buffer, "opacity", 7)) {
   134          eOut = PLY::EST_Opacity;
   135      } else if (PLY::DOM::TokenMatch(buffer, "specular_power", 14)) {
   136          eOut = PLY::EST_PhongPower;
   137      } else if (PLY::DOM::TokenMatch(buffer, "r", 1)) {
   138          eOut = PLY::EST_Red;
   139      } else if (PLY::DOM::TokenMatch(buffer, "g", 1)) {
   140          eOut = PLY::EST_Green;
   141      } else if (PLY::DOM::TokenMatch(buffer, "b", 1)) {
   142          eOut = PLY::EST_Blue;
   143      }
   144
   145      // NOTE: Blender3D exports texture coordinates as s,t tuples
   146      else if (PLY::DOM::TokenMatch(buffer, "u", 1) || PLY::DOM::TokenMatch(buffer, "s", 1) || PLY::DOM::TokenMatch(buffer, "tx", 2) || PLY::DOM::TokenMatch(buffer, "texture_u", 9)) {
   147          eOut = PLY::EST_UTextureCoord;
   148      } else if (PLY::DOM::TokenMatch(buffer, "v", 1) || PLY::DOM::TokenMatch(buffer, "t", 1) || PLY::DOM::TokenMatch(buffer, "ty", 2) || PLY::DOM::TokenMatch(buffer, "texture_v", 9)) {
   149          eOut = PLY::EST_VTextureCoord;
   150      } else if (PLY::DOM::TokenMatch(buffer, "x", 1)) {
   151          eOut = PLY::EST_XCoord;
   152      } else if (PLY::DOM::TokenMatch(buffer, "y", 1)) {
   153          eOut = PLY::EST_YCoord;
   154      } else if (PLY::DOM::TokenMatch(buffer, "z", 1)) {
   155          eOut = PLY::EST_ZCoord;
   156      } else if (PLY::DOM::TokenMatch(buffer, "nx", 2)) {
   157          eOut = PLY::EST_XNormal;
   158      } else if (PLY::DOM::TokenMatch(buffer, "ny", 2)) {
   159          eOut = PLY::EST_YNormal;
   160      } else if (PLY::DOM::TokenMatch(buffer, "nz", 2)) {
   161          eOut = PLY::EST_ZNormal;
   162      } else {
   163          ASSIMP_LOG_INFO("Found unknown property semantic in file. This is ok");
   164          PLY::DOM::SkipLine(buffer);
   165      }
