   170  bool PLY::Property::ParseProperty(std::vector<char> &buffer, PLY::Property *pOut) {
   171      ai_assert(!buffer.empty());
   172
   173      // Forms supported:
   174      // "property float x"
   175      // "property list uchar int vertex_index"
   176
   177      // skip leading spaces
   178      if (!PLY::DOM::SkipSpaces(buffer)) {
   179          return false;
   180      }
   181
   182      // skip the "property" string at the beginning
   183      if (!PLY::DOM::TokenMatch(buffer, "property", 8)) {
   184          // seems not to be a valid property entry
   185          return false;
   186      }
   187      // get next word
   188      if (!PLY::DOM::SkipSpaces(buffer)) {
   189          return false;
   190      }
   191      if (PLY::DOM::TokenMatch(buffer, "list", 4)) {
   192          pOut->bIsList = true;
   193
   194          // seems to be a list.
   195          if (EDT_INVALID == (pOut->eFirstType = PLY::Property::ParseDataType(buffer))) {
   196              // unable to parse list size data type
   197              PLY::DOM::SkipLine(buffer);
   198              return false;
   199          }
   200          if (!PLY::DOM::SkipSpaces(buffer)) return false;
   201          if (EDT_INVALID == (pOut->eType = PLY::Property::ParseDataType(buffer))) {
   202              // unable to parse list data type
   203              PLY::DOM::SkipLine(buffer);
   204              return false;
   205          }
   206      } else {
   207          if (EDT_INVALID == (pOut->eType = PLY::Property::ParseDataType(buffer))) {
   208              // unable to parse data type. Skip the property
   209              PLY::DOM::SkipLine(buffer);
   210              return false;
   211          }
   212      }
   213
   214      if (!PLY::DOM::SkipSpaces(buffer))
   215          return false;
   216
   217      pOut->Semantic = PLY::Property::ParseSemantic(buffer);
   218
   219      if (PLY::EST_INVALID == pOut->Semantic) {
   220          ASSIMP_LOG_INFO("Found unknown semantic in PLY file. This is OK");
   221          std::string(&buffer[0], &buffer[0] + strlen(&buffer[0]));
   222      }
   223
   224      PLY::DOM::SkipSpacesAndLineEnd(buffer);
   225      return true;
   226  }
