   229  PLY::EElementSemantic PLY::Element::ParseSemantic(std::vector<char> &buffer) {
   230      ai_assert(!buffer.empty());
   231
   232      PLY::EElementSemantic eOut = PLY::EEST_INVALID;
   233      if (PLY::DOM::TokenMatch(buffer, "vertex", 6)) {
   234          eOut = PLY::EEST_Vertex;
   235      } else if (PLY::DOM::TokenMatch(buffer, "face", 4)) {
   236          eOut = PLY::EEST_Face;
   237      } else if (PLY::DOM::TokenMatch(buffer, "tristrips", 9)) {
   238          eOut = PLY::EEST_TriStrip;
   239      }
   240  #if 0
   241    // TODO: maybe implement this?
   242    else if (PLY::DOM::TokenMatch(buffer,"range_grid",10))
   243    {
   244      eOut = PLY::EEST_Face;
   245    }
   246  #endif
   247      else if (PLY::DOM::TokenMatch(buffer, "edge", 4)) {
   248          eOut = PLY::EEST_Edge;
   249      } else if (PLY::DOM::TokenMatch(buffer, "material", 8)) {
   250          eOut = PLY::EEST_Material;
   251      } else if (PLY::DOM::TokenMatch(buffer, "TextureFile", 11)) {
   252          eOut = PLY::EEST_TextureFile;
   253      }
   254
   255      return eOut;
   256  }
